#!/usr/bin/env python3
"""Render measured status and a local handover after the mandatory Step 3 stop."""
import argparse,csv,hashlib,json,subprocess
from pathlib import Path
from experiment import BASE,EXPERIMENT,REPO,SCOPE

def read(path):return json.loads((EXPERIMENT/path).read_text())
def git(repo,*args):return subprocess.check_output(['git','-C',str(repo),*args],text=True).strip()
def report():
 inventory=read('tools/jar-inventory.json');fetch=read('results/classpath-fetch.json');smoke=read('results/classpath-smoke.json');baseline=read('results/developer-baseline.json');commits=read('results/commits-check.json');unresolved=[x for x in fetch['entries'] if not x['resolved']]
 lines=['# Fixed generated-test classpath and smoke commands','','Status: **Step 3 incomplete; Part 1 stopped here under the repeated-failure rule.** Exact supplied EvoSuite and JaCoCo coordinates did not resolve from Maven Central. No alternate versions/repositories or supplied-jar copies were used to bypass that failure. Population generation and the persistent compose override were not started.','','All numbers below come from tools/jar-inventory.json, results/classpath-fetch.json, and results/classpath-smoke.json. Measurements were made with these commands:', '', '```sh', 'python3 experiments/ktester-commit-survival/tools/inventory_classpath.py --kt /Users/donggi/_projects/experiment-projects/KTester', '# From KTester/docker:', "docker compose run --rm -v /Users/donggi/_projects/experiment-projects/commons-codec:/repo ktester bash -c '/repo/experiments/ktester-commit-survival/tools/fetch-llm-classpath.sh'", "docker compose run --rm -v /Users/donggi/_projects/experiment-projects/commons-codec:/repo ktester bash -c 'python /repo/experiments/ktester-commit-survival/tools/smoke_classpath.py'",'```','', 'Render this report with `python3 experiments/ktester-commit-survival/tools/report_part1.py`.','',f"Requested {fetch['requested']} supplied jars; resolved {fetch['resolved']}; unresolved {len(unresolved)}. Every resolved jar’s SHA-256 equals its supplied counterpart. Names, byte sizes, embedded Maven coordinates and manifests are recorded in jar-inventory.md/json. llm-classpath.txt lists one primary coordinate per jar; comments identify inferred coordinates where pom.properties is absent. Fetching uses the compose ktester-m2 volume at /root/.m2, online mode, and pinned maven-dependency-plugin 3.8.1. No jar is committed.",'','## Unresolved exact artifacts','','| Supplied jar | Requested coordinate | Classifier | Failed attempts | Evidence |','|---|---|---|---:|---|']
 for e in unresolved:lines.append(f"| {e['filename']} | {e['coordinate']} | {e['classifier'] or '(none)'} | {len(e['attempts'])} | {e['attempts'][-1]['log']} |")
 lines+=['','Each Maven log reports that the requested artifact is absent from https://repo.maven.apache.org/maven2. JaCoCo agent pom.properties names the internal org.jacoco.agent.rt module, and both JaCoCo jars use snapshot versions. A published agent runtime classifier/release is not silently substituted. EvoSuite is inventoried because the instruction includes code/dependencies; it is not needed to execute this standalone JUnit smoke test.','','## Independent compile and launcher smoke','','The original Md5Crypt_md5Crypt_Test.java was selected because the Stage 4c coverage log records its successful compilation and execution: `rg -n "Md5Crypt_md5Crypt_Test" KTester/results/stage4c/commons-codec/stage4c-commons-codec-coverage.log`. Only an ignored working copy under work/smoke/ is used here; the authored test is not committed. Its hash is in results/classpath-smoke.json.','', 'The smoke uses the resolved project libraries plus the console standalone jar. Runtime classpath order explicitly places project libraries before the console bundle, as KTester does; this avoids relying on wildcard order for overlapping JUnit classes. This verifies compilation and execution only. It does not satisfy the missing-artifact requirement or establish coverage tooling.','', 'Working directory inside the container: `/repo/experiments/ktester-commit-survival`. Exact commands:', '', '```sh']
 lines.extend(x['shell_command'] for x in smoke['runs']);lines+=['```','',f"Compile exit: {smoke['runs'][0]['exit_code']} ({smoke['runs'][0]['seconds']} s). Launcher exit: {smoke['runs'][1]['exit_code']} ({smoke['runs'][1]['seconds']} s). Launcher XML reports {smoke['counts']['tests']} tests, {smoke['counts']['failures']} failures, {smoke['counts']['errors']} errors, {smoke['counts']['skipped']} skipped. Assertion failures are allowed for this smoke criterion; the launcher did execute the class. Full output is in results/classpath-smoke-compile.txt and results/classpath-smoke-launch.txt. Public logs normalize trailing whitespace; exact raw output is retained locally under ignored work/raw-logs/.",'','## Stop condition','','The controlling Part 1 instructions say: “If a command fails twice for the same reason, record it and stop at the end of the current step with a handover rather than improvising around it.” Each unresolved artifact failed both bounded attempts. The independent smoke check finishes the current step’s usable evidence; the overall classpath remains blocked. Do not treat this status as permission to start Part 2.']
 (EXPERIMENT/'tools/README.md').write_text('\n'.join(lines)+'\n')
 status={'status':'blocked_at_end_of_step_3','completed_steps':[1,2],'incomplete_step':3,'not_started':[4,5],'developer_denominator':baseline['developer_denominator'],'selected_commits':commits['selected_rows'],'scope_changing_commits':commits['selected_scope_changes'],'unresolved_artifacts':[{'filename':e['filename'],'coordinate':e['coordinate'],'classifier':e['classifier'],'attempts':len(e['attempts'])} for e in unresolved],'population':'not enumerated or generated','overload_check':'not run','llm_calls':0,'author_index_rebuilt':False,'pushes':0}
 (EXPERIMENT/'results/part1-status.json').write_text(json.dumps(status,indent=2)+'\n')
 lines=['# Part 1 stop report','','Status: stopped at the end of Step 3 under the explicit repeated-failure rule. Steps 1 and 2 are complete; Step 3 has complete inventory/fetch failure evidence and a successful compile/launcher smoke criterion, but the exact artifact set is incomplete. Steps 4 and 5 are not started. This is not a completed Part 1.','','All numbers below are rendered by `python3 experiments/ktester-commit-survival/tools/report_part1.py` from results/commits-check.json, results/developer-baseline.json, results/classpath-fetch.json and results/classpath-smoke.json; their measurement invocations are in results/commits-check.md, dev/README.md and tools/README.md.','',f"- Fixed history: {commits['selected_rows']} commits after {BASE}; {commits['selected_scope_changes']} change scoped source files. Range is unchanged.",f"- Developer methods: {baseline['scope_methods']} in scope, {baseline['developer_denominator']} pass every run; whole-suite reference {baseline['whole_methods']} methods, {baseline['whole_pass_all']} pass every run.",f"- Classpath: {fetch['resolved']}/{fetch['requested']} exact supplied artifacts resolved and byte-identical; remaining artifacts failed both attempts. See tools/README.md for coordinates and logs.",f"- Smoke criterion passed: compilation succeeds and the launcher executes {smoke['counts']['tests']} tests, with {smoke['counts']['failures']} assertion failures allowed by the instruction.",'- Population count and overload uniqueness: not measured; no dataset_meta.json or dataset_info.json was created.','- No model calls, generation, project-index rebuild, or remote push occurred. KTester pipeline, settings and author data were only read.','- Temporary /repo mounts were supplied with compose run -v for Steps 2 and 3. Existing compose.yml and Maven cache mounts were unchanged; Step 5 persistent wiring was not created.','- Root ignore rules for work/ and docs/handover-*.md were brought forward solely to retain the mandated stop handover locally. The handover is written after the final commit so it contains actual final hashes.','', 'TODO (Gary): Decide how the exact missing auxiliary artifacts should be obtained, or explicitly revise their inclusion/version policy before resuming. No substitution was made.','TODO (Gary): Review the scope-change milestones in commits-check.md; the prescribed range remains fixed.','TODO (Gary): After resolving the Step 3 blocker, resume with focal-population enumeration and DatasetPrepare overload/missing-entry checks, then container wiring.']
 (EXPERIMENT/'results/part1-status.md').write_text('\n'.join(lines)+'\n')

def handover(kt):
 b=read('results/developer-baseline.json');c=read('results/commits-check.json');f=read('results/classpath-fetch.json');s=read('results/classpath-smoke.json');inventory=read('tools/jar-inventory.json')
 lines=['# Part 1 handover — stopped after Step 3','','Part 1 is incomplete. The controlling instruction requires a stop at the end of the current step after the same command failure occurs twice. Exact EvoSuite and JaCoCo artifact resolution failed both attempts; no versions were substituted. Steps 1 and 2 are complete, Step 3 is partial, and population generation/overload checks plus persistent container wiring are not started. See ../results/part1-status.md and ../tools/README.md.','','Every number below comes from the referenced measured JSON files via `python3 experiments/ktester-commit-survival/tools/report_part1.py --handover --kt '+str(kt)+'`. Git identities come from `git branch --show-current` and `git rev-parse HEAD`; commands used for all measurements are recorded beside their source reports.','','## Final repository state','',f"- commons-codec: `{git(REPO,'branch','--show-current')}` at `{git(REPO,'rev-parse','HEAD')}`.",f"- KTester: `{git(kt,'branch','--show-current')}` at `{git(kt,'rev-parse','HEAD')}`; no Part 1 tracked changes were made there because the population step was not reached.",'- Neither repository was pushed. All new commits use the required Codex co-author trailer.','- KTester’s pre-existing untracked Claude outputs/ and docs/cc-instructions-part1-commit-survival.md were left untouched.','- Commons-codec experiment changes are confined to experiments/ktester-commit-survival/ plus the explicitly requested root .gitignore rules. work/ and this handover are ignored.','','## Developer denominator and fixed history','',f"Developer denominator: **{b['developer_denominator']}** methods. There are {b['scope_methods']} scoped methods, with Base64Test.testCodec265 skipped in every run. Whole-suite reference: {b['whole_methods']} concrete-class/method units, {b['whole_pass_all']} passing every run. Source: ../results/developer-baseline.json; frozen sources and denominator CSV are under ../dev/.",'','| Run | Cases | Failures | Errors | Skipped | Wall seconds |','|---:|---:|---:|---:|---:|---:|']
 for i,r in enumerate(b['runs'],1):
  t=r['totals'];lines.append(f"| {i} | {t['tests']} | {t['failures']} | {t['errors']} | {t['skipped']} | {r['seconds']} |")
 lines += ['',f"The range remains {c['selected_rows']} commits with {c['selected_scope_changes']} scope-changing commits. Scope milestones and SHA/date evidence are in ../results/commits-check.json and commits-check.md.",'','## Population','','Population size: not enumerated. Overload uniqueness: not checked. No enlarged dataset was created in either repository. Fixed classes from the instruction (tools/experiment.py):','']
 lines += ['- '+x for x in SCOPE]
 lines += ['','## Classpath and runner','',f"Exact artifacts resolved: {f['resolved']} of {f['requested']}; every resolved jar matches the supplied SHA-256. Source: ../results/classpath-fetch.json. Coordinates and missing status:",'']
 failed={e['filename'] for e in f['entries'] if not e['resolved']}
 for e in inventory:lines.append('- `'+e['coordinate']+'`'+(' classifier='+e['classifier'] if e['classifier'] else '')+' — '+('UNRESOLVED' if e['filename'] in failed else 'resolved')+' ('+e['filename']+').')
 lines+=['','Working directory: /repo/experiments/ktester-commit-survival. Exact smoke commands recorded in ../results/classpath-smoke.json:','','```sh',*[r['shell_command'] for r in s['runs']],'```','',f"The compile succeeds; the launcher executes {s['counts']['tests']} tests with {s['counts']['failures']} assertion failures (allowed for smoke). This does not establish availability of the missing coverage/tool artifacts. The authored source remains only in ignored work/smoke/ and was not committed.",'','## Deviations and open questions','','- Used temporary compose run -v /repo mounts for baseline and classpath tasks; Step 5 persistent override was not reached. Original compose mounts and the shared Maven cache were retained.','- Root ignore entries and this local handover were written at the mandatory early stop, rather than waiting for the ordinary final step.','- A supplementary source-annotation audit was attempted once but could not import the existing cached tree-sitter native binding. It was not used for any counts; developer counts come from the preserved Surefire evidence. No population parser run was attempted.','- The whole-suite reference differs from the rough source annotation estimate because method units include concrete execution classes and inherited tests. The scoped set matches the expected class/method inventory; the only denominator reduction is the skipped Base64 method.','','TODO (Gary): Specify an approved reproducible source or changed inclusion/version policy for EvoSuite and the JaCoCo snapshot artifacts. The embedded JaCoCo agent coordinate is an internal module; a published runtime classifier/release was not substituted.','TODO (Gary): After the classpath blocker is resolved, resume Step 4 exactly as specified, including all existing focal methods, the fixed classes and the stop-on-colliding-ID rule; then complete Step 5.','TODO (Gary): Review whether the measured scope-change count is sufficient; the chosen range was not altered.']
 out=EXPERIMENT/'docs/handover-part1.md';out.parent.mkdir(exist_ok=True);out.write_text('\n'.join(lines)+'\n');print(out)

if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--handover',action='store_true');ap.add_argument('--kt',type=Path);args=ap.parse_args()
 if args.handover:
  if args.kt is None:ap.error('--kt required for --handover')
  handover(args.kt)
 else:report()
